  outline: 2px solid var(--cd-focus-ring);
  outline-offset: 2px;
}

.confirm-dialog__button--secondary {
  background: var(--cd-button-bg);
  border-color: var(--cd-button-border);
  color: var(--cd-button-text);
}

.confirm-dialog__button--secondary:hover {
  background: var(--cd-button-bg-hover);
}

.confirm-dialog__button--danger {
  background: var(--cd-danger-bg);
  color: var(--cd-danger-text);
}

.confirm-dialog__button--danger:hover {
  background: var(--cd-danger-bg-hover);
}

@keyframes confirm-dialog-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes confirm-dialog-rise {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .confirm-dialog-backdrop,
  .confirm-dialog {
    animation: none;
  }

  .confirm-dialog__button {
    transition: none;
  }
}
